declare function record(value: { kind: "external"; status: "ok" | "failed"; target: string; bytes?: number; error?: string }): void;
export function report(options: { status?: string; bytes?: number; error?: string }) {
  if (options.status !== "ok" && options.status !== "failed") throw new Error("invalid status");
  const outcome = {
    kind: "external" as const,
    target: "synthetic",
    status: options.status,
    ...(options.bytes !== undefined ? { bytes: options.bytes } : {}),
    ...(options.error ? { error: options.error } : {}),
  };
  record(outcome);
}

type Input = { kind: "preview"; database: object; limit: number } | { kind: "title"; database: object; text: string };
type Prepared<T> = T extends unknown ? Omit<T, "database"> : never;
type Request = Prepared<Input>;
export function prepare<K extends Request["kind"], Value extends object>(kind: K, input: Value) {
  return { kind, ...input } as Extract<Request, { kind: K }>;
}
